import {rangePlayback,table} from './topic-tools.js';
import {detectionBoxes,overlap,suppressionTrace} from './detection-model.js';
const f=x=>Number(x.toFixed(4)).toString();
const accessibleTable=(caption,heads,rows)=>table(caption,heads,rows).replace('class="dense-table-wrap"','class="dense-table-wrap" tabindex="0" role="region" aria-label="'+caption+'"');
export function detectionGeometryBody(offset=40){if(!Number.isInteger(offset)||offset<0||offset>160)throw new RangeError('Invalid horizontal displacement');const a=[0,0,100,100],b=[offset,0,offset+100,100],m=overlap(a,b);return '<div class="detection-plot" tabindex="0" role="region" aria-label="Two boxes with an independently movable horizontal displacement"><svg viewBox="-10 -25 290 155" role="img" aria-label="Two 100 by 100 boxes; their intersection is shaded. Exact areas and similarities follow."><rect x="0" y="0" width="100" height="100" fill="#bad6fa22" stroke="#bad6fa" stroke-width="2"/><rect x="'+offset+'" y="0" width="100" height="100" fill="#88425822" stroke="#d99ab4" stroke-width="2"/>'+(offset<100?'<rect x="'+offset+'" y="0" width="'+(100-offset)+'" height="100" fill="#bad6fa66"/>':'')+'<text x="0" y="-8">A</text><text x="'+offset+'" y="118">B</text><line x1="50" y1="50" x2="'+(50+offset)+'" y2="50" stroke="#f1e5ec" stroke-dasharray="4 3"/><circle cx="50" cy="50" r="3" fill="#f1e5ec"/><circle cx="'+(50+offset)+'" cy="50" r="3" fill="#f1e5ec"/></svg></div><p data-geometry-result>Displacement='+offset+'. Intersection area='+m.intersection+'; union area='+m.union+'; IoU=<strong>'+f(m.iou)+'</strong>. Normalized center penalty='+f(m.centerPenalty)+'; DIoU similarity='+f(m.diou)+'.</p><p>Both boxes have area10,000. The dashed line joins their centers. Moving B changes overlap and center separation, not scores or labels. These are exact continuous-coordinate rectangles.</p>';}
export function detectionTraceBody(method='hard',percent=50,classAware=true,step=0){if(!Number.isInteger(step)||step<0||step>5)throw new RangeError('Invalid display round');if(!Number.isInteger(percent)||percent<0||percent>100)throw new RangeError('Invalid display threshold');const trace=suppressionTrace(detectionBoxes,{method,threshold:percent/100,classAware}),round=Math.min(step,trace.length-1),m=trace[round],all=new Map([...m.kept,...m.remaining,...m.removed].map(b=>[b.id,b]));
 const state=id=>m.removed.some(b=>b.id===id)?'Removed':m.selected?.id===id?'Selected now':m.kept.some(b=>b.id===id)?'Kept':'Pending';
 const chart='<svg viewBox="0 0 275 150" role="img" aria-label="Five assigned detection boxes; IDs and current status are also listed in the score table">'+detectionBoxes.map((b,i)=>{const [x,y,x2,y2]=b.box,s=state(b.id),removed=s==='Removed',kept=s==='Kept'||s==='Selected now',color=removed?'#d99ab4':kept?'#bad6fa':'#b4a1b7';return '<g><rect x="'+x+'" y="'+y+'" width="'+(x2-x)+'" height="'+(y2-y)+'" stroke="'+color+'" stroke-width="'+(s==='Selected now'?3:1.5)+'" fill="'+(kept?'#bad6fa15':'none')+'"'+(removed?' stroke-dasharray="5 4"':'')+'/>'+(removed?'<line x1="'+x+'" y1="'+y+'" x2="'+x2+'" y2="'+y2+'" stroke="'+color+'"/>':'')+'<text x="'+(x+4)+'" y="'+(b.id==='E'?y2-5:y+14+(i===1?12:0))+'">'+b.id+'</text></g>';}).join('')+'</svg>';
 const rows=detectionBoxes.map(b=>{const current=all.get(b.id);return [b.id+' · '+b.label,f(b.score),f(current.score),state(b.id)];});
 const comparisons=m.comparisons.length?'<ul class="detection-comparisons">'+m.comparisons.map(c=>'<li><strong>'+m.selected.id+' → '+c.id+'</strong>: '+(!c.comparable?'different labels; no suppression.':'IoU='+f(c.iou)+'; DIoU='+f(c.diou)+'; score '+f(c.before)+' → '+f(c.after)+'. '+(c.reason?'Remove: '+c.reason+'.':'Remain eligible.'))+'</li>').join('')+'</ul>':'<p>No comparisons yet. All initial candidates meet the .1 score floor.</p>';
 return '<p data-trace-result>Round='+round+'/'+(trace.length-1)+'; selected='+(m.selected?.id||'none')+'; kept='+(m.kept.map(b=>b.id).join(',')||'none')+'; pending='+(m.remaining.map(b=>b.id).join(',')||'none')+'; removed='+(m.removed.map(b=>b.id).join(',')||'none')+'.</p><div class="detection-layout"><div class="detection-plot" tabindex="0" role="region" aria-label="Detection boxes at the selected suppression round">'+chart+'</div>'+accessibleTable('Original versus current scores',['Candidate','Original','Current','State'],rows)+'</div>'+comparisons+'<p>Policy: '+(classAware?'class-aware':'class-agnostic')+' '+method+'; overlap threshold='+f(percent/100)+'. Gaussian mode instead uses fixed σ=.5; its overlap threshold control has no effect. Score floor=.1 in all modes. Equal current scores use original A–E order. Selected boxes leave the pending pool; removed boxes never return.</p><p>Assigned coordinates, scores and labels—not detector measurements or ground truth. A retained box is not automatically a true positive. A late requested round shows the final state if the algorithm finished earlier.</p>';
}
export function detectionScenes(){return {
 geometry:'<figure class="topic-scene" data-detection-lab="geometry"><h3>Separate overlap from center distance</h3><label>Horizontal displacement<input aria-label="Detection horizontal displacement" type="range" min="0" max="160" step="1" value="40"></label><div data-body>'+detectionGeometryBody()+'</div><figcaption>Original geometric illustration. IoU reaches zero when boxes cease to overlap; center distance still distinguishes separated boxes.</figcaption></figure>',
 trace:'<figure class="topic-scene" data-detection-lab="trace"><h3>Watch the candidate pool change</h3><div class="detection-controls"><label>Suppression method<select aria-label="Detection suppression method"><option value="hard">Hard NMS</option><option value="linear">Linear Soft-NMS</option><option value="gaussian">Gaussian Soft-NMS</option><option value="diou">DIoU-NMS</option></select></label><label>Label policy<select aria-label="Detection label policy"><option value="aware">Class-aware</option><option value="agnostic">Class-agnostic</option></select></label></div><label>Overlap threshold (%)<input aria-label="Detection overlap threshold" type="range" min="0" max="100" step="1" value="50"></label><label>Suppression round<input aria-label="Detection suppression round" type="range" min="0" max="5" step="1" value="0"></label><div class="dense-actions"><button data-play>Play</button><button data-reset>Replay</button></div><div data-body>'+detectionTraceBody()+'</div><figcaption>One round selects the current maximum and processes every remaining comparable box. Manual rounds and optional playback expose the same exact states.</figcaption></figure>'
};}
export function mountDetectionScenes(article){const geometry=article.querySelector('[data-detection-lab="geometry"]');if(geometry){const input=geometry.querySelector('input');input.addEventListener('input',()=>{geometry.querySelector('[data-body]').innerHTML=detectionGeometryBody(Number(input.value));});}const lab=article.querySelector('[data-detection-lab="trace"]');if(!lab)return;const method=lab.querySelector('[aria-label="Detection suppression method"]'),policy=lab.querySelector('[aria-label="Detection label policy"]'),threshold=lab.querySelector('[aria-label="Detection overlap threshold"]'),stage=lab.querySelector('[aria-label="Detection suppression round"]');const draw=()=>{threshold.disabled=method.value==='gaussian';threshold.setAttribute('aria-description',method.value==='gaussian'?'Unused in Gaussian mode. This mode uses fixed sigma .5.':'Similarity threshold for the selected method.');lab.querySelector('[data-body]').innerHTML=detectionTraceBody(method.value,Number(threshold.value),policy.value==='aware',Math.round(Number(stage.value)));};const playback=rangePlayback(article,lab,draw,16000,stage);for(const control of [method,policy,threshold])control.addEventListener(control===threshold?'input':'change',()=>{playback.stop();draw();});}
